// Seeded noise sources: deterministic white noise and one-pole high-pass
// filtered noise bursts (GUIDELINES §3: pure functions, no module state).
//
// Determinism matters in two places: the test suite asserts that re-renders
// are byte-identical, and the UI previews (step 13) must not change between
// reloads of the same patch. Every buffer is generated by mulberry32 with an
// explicit seed chosen per voice.

// mulberry32: a tiny 32-bit LCG-style PRNG — an additive LCG state step
// (a ← a + 0x6d2b79f5, mod 2^32) followed by a multiply-xor-shift output
// mix. Integer-only math, so the same seed yields the same [0, 1) float
// sequence on every platform (no Math.random anywhere in the engine).
//
// Per-voice seed choices (keep these stable — a new seed re-shapes the
// transient, which is fine but changes the sound):
//   1 → kick click layer        (src/lib/voices/kick.js, step 10)
//   2 → snare snare-wire layer  (src/lib/voices/snare.js, step 11)
//   3, 4, 5 → clap slaps 1/2/3  (src/lib/voices/clap.js, P9/S23 —
//   distinct seeds so the three bursts don't reinforce/cancel into one)
export const mulberry32 = (seed) => {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
};

// `length` samples of white noise in [-1, 1) from the seeded PRNG.
// 2u − 1 maps the PRNG's [0, 1) output onto [-1, 1).
export const whiteNoiseBuffer = (length, seed) => {
  const buf = new Float32Array(length);
  const rand = mulberry32(seed);
  for (let n = 0; n < length; n++) buf[n] = 2 * rand() - 1;
  return buf;
};

// One-pole high-pass filtered noise burst with an exponential amplitude
// decay — the "attack click" / "snare wire" source of the kick and snare
// voices. Parameters: `length` in samples, `sr` the render sample rate,
// `seed` the PRNG seed (see mulberry32), `cutoff` in Hz, and `decay` the
// envelope time constant in seconds.
//
// The filter is a one-pole high-pass (RBJ-style first-order section):
//
//   y[n] = (1 − a/2)·(x[n] − x[n−1]) − (1 − a)·y[n−1]
//   a = 1 − exp(−2π·cutoff/sr)
//
// Note: the original plan draft wrote y[n] = y[n−1] + a·(x[n] − x[n−1]).
// That transfer function simplifies to H(z) = a·(1−z⁻¹)/(1−z⁻¹) = a — the
// (1 − z⁻¹) factors cancel — i.e. a pure gain with no high-pass character
// (verified numerically: its output is a·x apart from the start transient).
// The form above keeps the same coefficient `a` but has a zero at DC and a
// pole at z = −(1−a), so it actually kills DC, rolls off ≈ 6 dB/oct below
// `cutoff`, and passes the upper band (≈ 0.94 at 4 kHz for cutoff 2 kHz /
// sr 16 kHz). effects.js (step 7) reuses the same coefficient formula.
//
// The filtered signal is multiplied by an exponential envelope
// exp(−n/(sr·decay)) — the classic drum "controlled collapse" (see
// drum_generation.md) — and then peak-normalized to max |y| = 1: a
// one-pole high-pass of white noise peaks around ±2 (its gain rises toward
// Nyquist), so the burst is scaled to stay within ±1 for any seed and
// cutoff. The layer gain (src/lib/layer.js, step 6) sets final loudness in the
// mix; all spectral/decay tests are scale-invariant, so normalization does
// not hide any property.
export const filteredNoiseBurst = ({ length, sr, seed, cutoff, decay }) => {
  const x = whiteNoiseBuffer(length, seed);
  const a = 1 - Math.exp((-2 * Math.PI * cutoff) / sr);
  const y = new Float32Array(length);
  const tau = sr * decay; // envelope time constant in samples
  let yPrev = 0;
  let xPrev = 0;
  let peak = 0;
  for (let n = 0; n < length; n++) {
    y[n] = (1 - a / 2) * (x[n] - xPrev) - (1 - a) * yPrev;
    yPrev = y[n];
    xPrev = x[n];
    y[n] *= Math.exp(-n / tau);
    const mag = Math.abs(y[n]);
    if (mag > peak) peak = mag;
  }
  // Peak-normalize (see above). The guard keeps an all-zero input safe.
  if (peak > 0) {
    const scale = 1 / peak;
    for (let n = 0; n < length; n++) y[n] *= scale;
  }
  return y;
};
